customScreen.css:
:root {
  --bg-0: #0b1020;
  --bg-1: #111a33;
  --card: rgba(255, 255, 255, 0.045);
  --card-brd: rgba(255, 255, 255, 0.09);
  --card-hi: rgba(255, 255, 255, 0.14);
  --ink: #eef2ff;
  --ink-dim: #a6b0cf;
  --ink-mut: #6c789e;
  --accent: #818cf8;
  --accent-2: #34d399;
  --accent-3: #fbbf24;
  --accent-4: #f472b6;
  --danger: #fb7185;
  --track: rgba(255, 255, 255, 0.08);
  --shadow: 0 18px 45px -22px rgba(0, 0, 0, 0.85);
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
  background:
    radial-gradient(1100px 620px at 12% -8%, rgba(129, 140, 248, 0.20), transparent 60%),
    radial-gradient(900px 560px at 108% 6%, rgba(52, 211, 153, 0.14), transparent 55%),
    linear-gradient(160deg, var(--bg-0), var(--bg-1) 62%, #0a0f1e);
  background-attachment: fixed;
  -webkit-font-smoothing: antialiased;
}

#app { max-width: 1180px; margin: 0 auto; padding: 28px 22px 56px; }

.boot { padding: 80px 0; text-align: center; color: var(--ink-dim); font-size: 15px; }

/* ---- header ---- */
.hdr {
  display: flex; flex-wrap: wrap; gap: 18px;
  align-items: flex-end; justify-content: space-between;
  margin-bottom: 26px;
}
.hdr .brand { display: flex; align-items: center; gap: 14px; min-width: 0; }
.hdr .logo {
  width: 46px; height: 46px; flex: none; border-radius: 13px;
  display: grid; place-items: center; font-size: 22px;
  background: linear-gradient(140deg, var(--accent), #6366f1);
  box-shadow: 0 10px 26px -10px rgba(99, 102, 241, 0.75);
}
.hdr h1 { margin: 0; font-size: 22px; font-weight: 700; letter-spacing: -0.01em; }
.hdr .sub { margin: 3px 0 0; color: var(--ink-dim); font-size: 13px; }
.actions { display: flex; flex-wrap: wrap; gap: 10px; }

.btn {
  appearance: none; cursor: pointer; border: 1px solid var(--card-brd);
  background: var(--card); color: var(--ink);
  padding: 9px 15px; border-radius: 11px; font-size: 13px; font-weight: 600;
  display: inline-flex; align-items: center; gap: 8px;
  transition: transform .12s ease, background .12s ease, border-color .12s ease;
}
.btn:hover { transform: translateY(-1px); background: var(--card-hi); border-color: var(--card-hi); }
.btn:active { transform: translateY(0); }
.btn .ic { font-size: 14px; line-height: 1; }
.btn.primary {
  background: linear-gradient(135deg, var(--accent), #6366f1);
  border-color: transparent; color: #0b1020;
  box-shadow: 0 12px 26px -14px rgba(99, 102, 241, 0.9);
}
.btn.primary:hover { filter: brightness(1.06); }
.btn.ghost { background: transparent; }

/* ---- stat cards ---- */
.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 22px; }
.stat {
  position: relative; overflow: hidden;
  background: var(--card); border: 1px solid var(--card-brd);
  border-radius: 18px; padding: 18px 18px 16px; box-shadow: var(--shadow);
}
.stat::before {
  content: ""; position: absolute; inset: 0 0 auto 0; height: 3px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  opacity: .8;
}
.stat .k { color: var(--ink-dim); font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: .06em; }
.stat .v { font-size: 30px; font-weight: 750; margin-top: 8px; letter-spacing: -0.02em; }
.stat .m { color: var(--ink-mut); font-size: 12px; margin-top: 4px; }
.stat.ok::before { background: linear-gradient(90deg, var(--accent-2), #22d3ee); }
.stat.warn::before { background: linear-gradient(90deg, var(--accent-3), var(--accent-4)); }
.stat.info::before { background: linear-gradient(90deg, var(--accent-4), var(--accent)); }

/* ---- grid ---- */
.grid { display: grid; grid-template-columns: 1.35fr 1fr; gap: 16px; margin-bottom: 22px; }
.panel {
  background: var(--card); border: 1px solid var(--card-brd);
  border-radius: 18px; padding: 20px; box-shadow: var(--shadow);
}
.panel h2 {
  margin: 0 0 14px; font-size: 14px; font-weight: 700;
  display: flex; align-items: center; gap: 9px;
}
.panel h2 .badge {
  margin-left: auto; font-size: 11px; font-weight: 700; color: var(--ink-dim);
  background: var(--track); padding: 3px 9px; border-radius: 999px;
}

/* ---- completion ring ---- */
.ring-row { display: flex; align-items: center; gap: 18px; }
.ring {
  --pct: 0; width: 116px; height: 116px; flex: none; border-radius: 50%;
  background: conic-gradient(var(--accent) calc(var(--pct) * 1%), var(--track) 0);
  display: grid; place-items: center; position: relative;
}
.ring::after {
  content: ""; position: absolute; inset: 11px; border-radius: 50%;
  background: linear-gradient(160deg, #131c36, #0e1530);
  border: 1px solid var(--card-brd);
}
.ring .lbl { position: relative; text-align: center; z-index: 1; }
.ring .lbl b { font-size: 26px; font-weight: 780; }
.ring .lbl span { display: block; font-size: 10px; color: var(--ink-dim); letter-spacing: .06em; text-transform: uppercase; }
.ring-meta { color: var(--ink-dim); font-size: 13px; line-height: 1.6; }
.ring-meta b { color: var(--ink); }

/* ---- employee progress list ---- */
.emp { display: flex; flex-direction: column; gap: 14px; }
.emp .row { display: grid; grid-template-columns: 1fr auto; gap: 4px 12px; align-items: center; }
.emp .who { display: flex; align-items: center; gap: 10px; min-width: 0; }
.avatar {
  width: 30px; height: 30px; flex: none; border-radius: 9px; display: grid; place-items: center;
  font-size: 12px; font-weight: 700; color: #0b1020;
  background: linear-gradient(140deg, var(--accent-2), var(--accent));
}
.emp .name { font-size: 13px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.emp .dept { font-size: 11px; color: var(--ink-mut); }
.emp .frac { font-size: 12px; color: var(--ink-dim); font-variant-numeric: tabular-nums; }
.track { grid-column: 1 / -1; height: 8px; border-radius: 999px; background: var(--track); overflow: hidden; }
.track > i {
  display: block; height: 100%; border-radius: 999px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  transition: width .5s ease;
}
.track.full > i { background: linear-gradient(90deg, var(--accent-2), #22d3ee); }

/* ---- category bars ---- */
.cats { display: flex; flex-direction: column; gap: 13px; }
.cat .top { display: flex; justify-content: space-between; font-size: 12px; margin-bottom: 6px; }
.cat .top .c { color: var(--ink); font-weight: 600; }
.cat .top .n { color: var(--ink-dim); font-variant-numeric: tabular-nums; }
.cat .bar { height: 8px; border-radius: 999px; background: var(--track); overflow: hidden; }
.cat .bar > i { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, var(--accent-3), var(--accent-4)); }

/* ---- compliance ---- */
.comp { margin-top: 4px; }
.comp .stack { height: 12px; border-radius: 999px; overflow: hidden; display: flex; background: var(--track); }
.comp .stack > .ack { background: linear-gradient(90deg, var(--accent-2), #22d3ee); }
.comp .stack > .pend { background: linear-gradient(90deg, var(--accent-3), var(--danger)); }
.comp .legend { display: flex; gap: 18px; margin-top: 12px; font-size: 12px; color: var(--ink-dim); }
.comp .legend .dot { display: inline-block; width: 9px; height: 9px; border-radius: 3px; margin-right: 7px; vertical-align: middle; }
.comp .legend b { color: var(--ink); }
.dot.g { background: var(--accent-2); }
.dot.y { background: var(--accent-3); }

/* ---- recent ---- */
.feed { display: flex; flex-direction: column; }
.feed .item { display: flex; align-items: center; gap: 12px; padding: 11px 0; border-top: 1px solid var(--card-brd); }
.feed .item:first-child { border-top: 0; }
.feed .ic {
  width: 30px; height: 30px; flex: none; border-radius: 9px; display: grid; place-items: center;
  font-size: 14px; background: var(--track);
}
.feed .ic.t { background: rgba(129, 140, 248, 0.18); }
.feed .ic.p { background: rgba(52, 211, 153, 0.18); }
.feed .ic.e { background: rgba(251, 191, 36, 0.18); }
.feed .txt { font-size: 13px; min-width: 0; }
.feed .txt .when { font-size: 11px; color: var(--ink-mut); margin-top: 1px; }

/* ---- empty ---- */
.empty { text-align: center; padding: 46px 20px; }
.empty .big { font-size: 40px; margin-bottom: 10px; }
.empty h3 { margin: 0 0 6px; font-size: 17px; }
.empty p { margin: 0 auto 20px; max-width: 420px; color: var(--ink-dim); font-size: 13px; line-height: 1.6; }
.empty .actions { justify-content: center; }

.muted { color: var(--ink-mut); font-size: 12px; padding: 8px 0; }

@media (max-width: 860px) {
  .stats { grid-template-columns: repeat(2, 1fr); }
  .grid { grid-template-columns: 1fr; }
}
@media (max-width: 460px) {
  .stats { grid-template-columns: 1fr; }
  #app { padding: 20px 14px 42px; }
}

