// Typed accessor for the app-scoped FormLogic SDK injected into the sandboxed iframe.
// window.FormLogic is the ONLY backend capability available to a custom screen.

export interface FLField {
  id: string;
  label: string;
  type: string;
}

export interface FLForm {
  formId: string;
  displayName: string;
  fields: FLField[];
}

export interface FLContext {
  appName: string;
  appSlug: string;
  forms: FLForm[];
}

export interface FLRecord {
  id: string;
  answers: Record<string, unknown>;
  submittedAt: string;
}

export interface FLUser {
  id: string;
  name: string;
  email: string;
}

export interface FLSdk {
  context(): Promise<FLContext>;
  forms(): Promise<FLForm[]>;
  submit(formId: string, answers: Record<string, unknown>): Promise<unknown>;
  records(formId: string, opts?: { limit?: number }): Promise<FLRecord[]>;
  currentUser(): Promise<FLUser | null>;
  navigate(target: string): void;
  toast: { success(msg: string): void; error(msg: string): void };
  escapeHtml(value: unknown): string;
}

// The bridge is installed on window by the runtime before this bundle executes.
export const FL: FLSdk = (window as unknown as { FormLogic: FLSdk }).FormLogic;

/** Escape any value before interpolating it into innerHTML (prevents stored-XSS from record data). */
export const esc = (value: unknown): string => FL.escapeHtml(value);

// Data layer: resolves form ids from the app context (by displayName, never hardcoded),
// pulls records via the SDK, and computes the metrics the dashboard renders.
import { FL, FLForm, FLRecord } from "./sdk";

// Value -> friendly label maps (dropdown options aren't exposed via the SDK context).
export const DEPT: Record<string, string> = {
  engineering: "Engineering",
  sales: "Sales",
  hr: "HR",
  finance: "Finance",
  ops: "Operations",
};

export const CATEGORY: Record<string, string> = {
  it: "IT",
  hr: "HR",
  legal: "Legal",
  facilities: "Facilities",
};

export const POLICY: Record<string, string> = {
  code_of_conduct: "Code of Conduct",
  security_policy: "Security Policy",
  data_privacy: "Data Privacy",
  handbook: "Employee Handbook",
};

export interface EmployeeProgress {
  id: string;
  name: string;
  dept: string;
  total: number;
  done: number;
  pct: number;
}

export interface CategoryStat {
  key: string;
  label: string;
  count: number;
}

export interface RecentItem {
  kind: "employee" | "task" | "policy";
  text: string;
  when: string;
}

export interface Dashboard {
  ready: boolean;
  employeesFormId: string | null;
  tasksFormId: string | null;
  policyFormId: string | null;
  totalEmployees: number;
  totalTasks: number;
  doneTasks: number;
  outstanding: number;
  completionPct: number;
  progress: EmployeeProgress[];
  categories: CategoryStat[];
  totalPolicies: number;
  acknowledged: number;
  pending: number;
  compliancePct: number;
  recent: RecentItem[];
}

function truthy(v: unknown): boolean {
  return v === true || v === 1 || v === "1" || v === "true" || v === "yes" || v === "on";
}

function str(v: unknown): string {
  return v == null ? "" : String(v);
}

function pct(part: number, whole: number): number {
  return whole > 0 ? Math.round((part / whole) * 100) : 0;
}

function findForm(forms: FLForm[], needles: string[]): FLForm | undefined {
  return forms.find((f) => {
    const name = (f.displayName || "").toLowerCase();
    return needles.some((n) => name.includes(n));
  });
}

async function safeRecords(formId: string | null): Promise<FLRecord[]> {
  if (!formId) return [];
  try {
    return await FL.records(formId, { limit: 500 });
  } catch {
    return [];
  }
}

export async function loadDashboard(): Promise<Dashboard> {
  const ctx = await FL.context();
  const forms = ctx.forms || [];

  // Resolve the three forms by display name so ids are never hardcoded.
  const tasksForm = findForm(forms, ["task"]);
  const policyForm = findForm(forms, ["policy", "acknowledg", "compliance"]);
  const employeesForm =
    forms.find(
      (f) => (f.displayName || "").toLowerCase().includes("employee") && f !== tasksForm && f !== policyForm,
    ) || findForm(forms, ["employee", "people", "staff", "team"]);

  const employeesFormId = employeesForm ? employeesForm.formId : null;
  const tasksFormId = tasksForm ? tasksForm.formId : null;
  const policyFormId = policyForm ? policyForm.formId : null;

  const [emps, tasks, pols] = await Promise.all([
    safeRecords(employeesFormId),
    safeRecords(tasksFormId),
    safeRecords(policyFormId),
  ]);

  // Employee lookup: id -> { name, dept }.
  const empMeta = new Map<string, { name: string; dept: string }>();
  for (const e of emps) {
    const a = e.answers;
    const deptVal = str(a.department);
    empMeta.set(e.id, {
      name: str(a.full_name) || "Unnamed",
      dept: DEPT[deptVal] || deptVal || "Unassigned",
    });
  }

  // Tasks: completion, per-employee tallies, outstanding-by-category.
  let doneTasks = 0;
  const perEmp = new Map<string, { total: number; done: number }>();
  const catOut = new Map<string, number>();
  for (const t of tasks) {
    const a = t.answers;
    const isDone = truthy(a.done);
    if (isDone) doneTasks += 1;

    const empId = str(a.employee);
    if (empId) {
      const cur = perEmp.get(empId) || { total: 0, done: 0 };
      cur.total += 1;
      if (isDone) cur.done += 1;
      perEmp.set(empId, cur);
    }

    if (!isDone) {
      const cat = str(a.category) || "other";
      catOut.set(cat, (catOut.get(cat) || 0) + 1);
    }
  }

  // Per-employee progress bars (people with the most outstanding work first).
  const progress: EmployeeProgress[] = [];
  for (const [id, meta] of empMeta) {
    const tally = perEmp.get(id) || { total: 0, done: 0 };
    progress.push({
      id,
      name: meta.name,
      dept: meta.dept,
      total: tally.total,
      done: tally.done,
      pct: pct(tally.done, tally.total),
    });
  }
  progress.sort((a, b) => {
    if (a.total === 0 && b.total !== 0) return 1;
    if (b.total === 0 && a.total !== 0) return -1;
    if (a.pct !== b.pct) return a.pct - b.pct;
    return b.total - a.total;
  });

  // Outstanding tasks by category — always show the four known buckets, plus any extras.
  const categories: CategoryStat[] = [];
  const seen = new Set<string>();
  for (const key of Object.keys(CATEGORY)) {
    categories.push({ key, label: CATEGORY[key], count: catOut.get(key) || 0 });
    seen.add(key);
  }
  for (const [key, count] of catOut) {
    if (!seen.has(key)) categories.push({ key, label: key, count });
  }

  // Compliance: acknowledged vs pending policy acknowledgements.
  let acknowledged = 0;
  for (const p of pols) {
    if (truthy(p.answers.acknowledged)) acknowledged += 1;
  }
  const totalPolicies = pols.length;
  const pending = Math.max(0, totalPolicies - acknowledged);

  // Recent activity feed across all three forms.
  const recent: RecentItem[] = [];
  for (const e of emps) {
    recent.push({
      kind: "employee",
      text: "Joined: " + (str(e.answers.full_name) || "New employee"),
      when: e.submittedAt,
    });
  }
  for (const t of tasks) {
    const verb = truthy(t.answers.done) ? "Completed task" : "New task";
    recent.push({ kind: "task", text: verb + ": " + (str(t.answers.title) || "Untitled"), when: t.submittedAt });
  }
  for (const p of pols) {
    const label = POLICY[str(p.answers.policy)] || "Policy";
    const state = truthy(p.answers.acknowledged) ? "acknowledged" : "pending";
    recent.push({ kind: "policy", text: label + " " + state, when: p.submittedAt });
  }
  recent.sort((a, b) => str(b.when).localeCompare(str(a.when)));

  return {
    ready: Boolean(employeesFormId || tasksFormId || policyFormId),
    employeesFormId,
    tasksFormId,
    policyFormId,
    totalEmployees: emps.length,
    totalTasks: tasks.length,
    doneTasks,
    outstanding: Math.max(0, tasks.length - doneTasks),
    completionPct: pct(doneTasks, tasks.length),
    progress,
    categories,
    totalPolicies,
    acknowledged,
    pending,
    compliancePct: pct(acknowledged, totalPolicies),
    recent: recent.slice(0, 8),
  };
}

// Entry point: wires the DOM to the FormLogic app-scoped SDK and renders the
// onboarding + compliance command centre. All record/user values pass through esc().
import { FL, esc } from "./sdk";
import { loadDashboard, Dashboard, EmployeeProgress, CategoryStat, RecentItem } from "./data";

const root = document.getElementById("app") as HTMLElement;

function initials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

function statCard(cls: string, k: string, v: string, m: string): string {
  return (
    '<div class="stat ' + cls + '">' +
    '<div class="k">' + esc(k) + "</div>" +
    '<div class="v">' + esc(v) + "</div>" +
    '<div class="m">' + esc(m) + "</div></div>"
  );
}

function completionPanel(d: Dashboard): string {
  return (
    '<section class="panel">' +
    "<h2>Onboarding completion</h2>" +
    '<div class="ring-row">' +
    '<div class="ring" style="--pct:' + d.completionPct + '">' +
    '<div class="lbl"><b>' + d.completionPct + "%</b><span>complete</span></div></div>" +
    '<div class="ring-meta">' +
    "<b>" + d.doneTasks + "</b> of <b>" + d.totalTasks + "</b> tasks done<br>" +
    "<b>" + d.outstanding + "</b> still outstanding<br>" +
    "across <b>" + d.totalEmployees + "</b> employees" +
    "</div></div></section>"
  );
}

function progressPanel(rows: EmployeeProgress[]): string {
  let body: string;
  if (rows.length === 0) {
    body = '<div class="muted">No employees yet. Add your first hire to start tracking onboarding.</div>';
  } else {
    body =
      '<div class="emp">' +
      rows
        .slice(0, 12)
        .map((e) => {
          const frac = e.total > 0 ? e.done + "/" + e.total + " tasks" : "no tasks yet";
          const cls = e.total > 0 && e.done === e.total ? "track full" : "track";
          return (
            '<div class="unit">' +
            '<div class="row"><div class="who">' +
            '<div class="avatar">' + esc(initials(e.name)) + "</div>" +
            '<div><div class="name">' + esc(e.name) + "</div>" +
            '<div class="dept">' + esc(e.dept) + "</div></div></div>" +
            '<div class="frac">' + esc(frac) + "</div></div>" +
            '<div class="' + cls + '"><i style="width:' + e.pct + '%"></i></div>' +
            "</div>"
          );
        })
        .join("") +
      "</div>";
  }
  return (
    '<section class="panel"><h2>Per-employee progress' +
    '<span class="badge">' + rows.length + " people</span></h2>" +
    body +
    "</section>"
  );
}

function categoryPanel(cats: CategoryStat[]): string {
  const max = Math.max(1, ...cats.map((c) => c.count));
  const total = cats.reduce((s, c) => s + c.count, 0);
  let body: string;
  if (total === 0) {
    body = '<div class="muted">No outstanding tasks. Everything is on track.</div>';
  } else {
    body =
      '<div class="cats">' +
      cats
        .map((c) => {
          const w = Math.round((c.count / max) * 100);
          return (
            '<div class="cat"><div class="top">' +
            '<span class="c">' + esc(c.label) + "</span>" +
            '<span class="n">' + c.count + "</span></div>" +
            '<div class="bar"><i style="width:' + w + '%"></i></div></div>'
          );
        })
        .join("") +
      "</div>";
  }
  return (
    '<section class="panel"><h2>Outstanding by category' +
    '<span class="badge">' + total + " open</span></h2>" +
    body +
    "</section>"
  );
}

function compliancePanel(d: Dashboard): string {
  let body: string;
  if (d.totalPolicies === 0) {
    body = '<div class="muted">No policy acknowledgements recorded yet.</div>';
  } else {
    const ackW = Math.round((d.acknowledged / d.totalPolicies) * 100);
    const pendW = 100 - ackW;
    body =
      '<div class="comp"><div class="stack">' +
      '<div class="ack" style="width:' + ackW + '%"></div>' +
      '<div class="pend" style="width:' + pendW + '%"></div></div>' +
      '<div class="legend">' +
      '<span><span class="dot g"></span><b>' + d.acknowledged + "</b> acknowledged</span>" +
      '<span><span class="dot y"></span><b>' + d.pending + "</b> pending</span>" +
      "</div></div>";
  }
  return (
    '<section class="panel"><h2>Policy compliance' +
    '<span class="badge">' + d.compliancePct + "%</span></h2>" +
    body +
    "</section>"
  );
}

function feedPanel(items: RecentItem[]): string {
  let body: string;
  if (items.length === 0) {
    body = '<div class="muted">Activity will appear here as your team onboards.</div>';
  } else {
    const glyph: Record<string, string> = { employee: "\u{1F464}", task: "✓", policy: "\u{1F4CB}" };
    const cls: Record<string, string> = { employee: "e", task: "t", policy: "p" };
    body =
      '<div class="feed">' +
      items
        .map(
          (it) =>
            '<div class="item"><div class="ic ' + cls[it.kind] + '">' + glyph[it.kind] + "</div>" +
            '<div class="txt">' + esc(it.text) + "</div></div>",
        )
        .join("") +
      "</div>";
  }
  return '<section class="panel"><h2>Recent activity</h2>' + body + "</section>";
}

function header(d: Dashboard): string {
  const q = (formId: string | null, cls: string, label: string, glyph: string): string =>
    formId
      ? '<button class="btn ' + cls + '" type="button" data-nav="' + esc(formId) + '">' +
        '<span class="ic">' + glyph + "</span>" + esc(label) + "</button>"
      : "";
  return (
    '<header class="hdr">' +
    '<div class="brand"><div class="logo">\u{1F680}</div>' +
    "<div><h1>People Onboarding &amp; Compliance</h1>" +
    '<p class="sub">Track new-hire onboarding and policy sign-off in real time</p></div></div>' +
    '<div class="actions">' +
    q(d.employeesFormId, "primary", "Add employee", "+") +
    q(d.tasksFormId, "", "New task", "+") +
    q(d.policyFormId, "", "Acknowledge policy", "+") +
    '<button class="btn ghost" type="button" data-refresh="1"><span class="ic">↻</span>Refresh</button>' +
    "</div></header>"
  );
}

function renderEmpty(d: Dashboard): string {
  const q = (formId: string | null, cls: string, label: string): string =>
    formId ? '<button class="btn ' + cls + '" type="button" data-nav="' + esc(formId) + '">' + esc(label) + "</button>" : "";
  return (
    header(d) +
    '<div class="panel"><div class="empty">' +
    '<div class="big">\u{1F331}</div>' +
    "<h3>Let's onboard your first hire</h3>" +
    "<p>Add an employee, assign their onboarding tasks, and capture policy acknowledgements. " +
    "Your live completion and compliance metrics will build automatically.</p>" +
    '<div class="actions">' +
    q(d.employeesFormId, "primary", "Add employee") +
    q(d.tasksFormId, "", "New onboarding task") +
    q(d.policyFormId, "", "Acknowledge a policy") +
    "</div></div></div>"
  );
}

function render(d: Dashboard): void {
  const hasData = d.totalEmployees > 0 || d.totalTasks > 0 || d.totalPolicies > 0;
  if (!hasData) {
    root.innerHTML = renderEmpty(d);
    return;
  }
  root.innerHTML =
    header(d) +
    '<div class="stats">' +
    statCard("info", "Employees", String(d.totalEmployees), "on the roster") +
    statCard("ok", "Onboarding", d.completionPct + "%", d.doneTasks + " of " + d.totalTasks + " tasks done") +
    statCard("warn", "Outstanding", String(d.outstanding), "tasks to complete") +
    statCard("", "Compliance", d.compliancePct + "%", d.acknowledged + " of " + d.totalPolicies + " acknowledged") +
    "</div>" +
    '<div class="grid">' +
    progressPanel(d.progress) +
    '<div style="display:flex;flex-direction:column;gap:16px">' +
    completionPanel(d) +
    categoryPanel(d.categories) +
    compliancePanel(d) +
    "</div></div>" +
    feedPanel(d.recent);
}

async function refresh(): Promise<void> {
  try {
    const d = await loadDashboard();
    render(d);
  } catch (err) {
    root.innerHTML =
      '<div class="panel"><div class="empty"><div class="big">⚠️</div>' +
      "<h3>Could not load the dashboard</h3><p>Please try refreshing in a moment.</p></div></div>";
    FL.toast.error("Failed to load onboarding data");
  }
}

// One delegated click handler survives every re-render of root.innerHTML.
root.addEventListener("click", (ev) => {
  const t = ev.target as HTMLElement;
  const nav = t.closest("[data-nav]") as HTMLElement | null;
  if (nav) {
    const fid = nav.getAttribute("data-nav");
    if (fid) FL.navigate(fid);
    return;
  }
  if (t.closest("[data-refresh]")) {
    void refresh();
  }
});

void refresh();
